#!/usr/bin/env python3
import sys, csv, re, argparse

NUM = re.compile(r'^\s*[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?\s*$')

def die(msg, code=2):
    sys.stderr.write("csvq: %s\n" % msg)
    sys.exit(code)

class P(argparse.ArgumentParser):
    def error(self, message):
        die(message)

def main():
    p = P(prog="csvq", add_help=True)
    p.add_argument("--where", action="append", default=[])
    p.add_argument("--select")
    p.add_argument("--sort")
    p.add_argument("--numeric", action="store_true")
    p.add_argument("--desc", action="store_true")
    p.add_argument("file")
    a = p.parse_args()

    wheres = []
    for w in a.where:
        if "=" not in w:
            die("invalid --where (expected COL=VALUE): %s" % w)
        c, v = w.split("=", 1)
        wheres.append((c, v))

    try:
        csv.field_size_limit(sys.maxsize)
        with open(a.file, newline="", encoding="utf-8-sig") as f:
            rows = list(csv.reader(f))
    except OSError as e:
        die("cannot read %s: %s" % (a.file, e.strerror), 1)
    if not rows:
        return
    header = rows[0]
    data = rows[1:]
    idx = {}
    for i, h in enumerate(header):
        idx.setdefault(h, i)

    sel = None
    if a.select is not None:
        sel = a.select.split(",")
    for c in [c for c, _ in wheres] + (sel or []) + ([a.sort] if a.sort is not None else []):
        if c not in idx:
            die("unknown column: %s" % c)

    def get(r, i):
        return r[i] if i < len(r) else ""

    for c, v in wheres:
        i = idx[c]
        data = [r for r in data if get(r, i) == v]

    if a.sort is not None:
        i = idx[a.sort]
        if a.numeric:
            good, bad = [], []
            for r in data:
                s = get(r, i)
                if NUM.match(s):
                    try:
                        good.append((float(s), r))
                        continue
                    except (ValueError, OverflowError):
                        pass
                bad.append(r)
            good.sort(key=lambda t: t[0], reverse=a.desc)
            data = [r for _, r in good] + bad
        else:
            data.sort(key=lambda r: get(r, i), reverse=a.desc)

    cols = [idx[c] for c in sel] if sel is not None else list(range(len(header)))
    out = csv.writer(sys.stdout, lineterminator="\n", quoting=csv.QUOTE_MINIMAL)
    out.writerow([header[i] for i in cols])
    for r in data:
        out.writerow([get(r, i) for i in cols])

if __name__ == "__main__":
    main()
